CREATE TEMP TABLE _survivor_ids AS
SELECT d.id
FROM public.developers d
WHERE public.jbj_developer_import_key(d.name) IN (
  SELECT DISTINCT public.jbj_developer_import_key(name) FROM _keep_names
)
OR d.name ILIKE 'Citi Developers';

-- Preserve projects: null out developer_id for developers about to be deleted
-- (FK is ON DELETE CASCADE — this prevents project loss)
UPDATE public.projects
SET developer_id = NULL
WHERE developer_id IS NOT NULL
  AND developer_id NOT IN (SELECT id FROM _survivor_ids);

-- Delete developers not in the curated Excel list
DELETE FROM public.developers
WHERE id NOT IN (SELECT id FROM _survivor_ids);